    try {
      await delay(100);
      const point=await js(`const select=document.querySelector(${JSON.stringify(selector)});select.scrollIntoView({block:'nearest'});${keyboard ? 'select.focus();' : ''}const rect=select.getBoundingClientRect();({x:Math.round(rect.left+rect.width/2),y:Math.round(rect.top+rect.height/2)})`);
      const zoom=window.webContents.getZoomFactor();point.x=Math.round(point.x*zoom);point.y=Math.round(point.y*zoom);
      if(keyboard) {window.webContents.sendInputEvent({type:'keyDown',keyCode:'Space'});window.webContents.sendInputEvent({type:'char',keyCode:' '});window.webContents.sendInputEvent({type:'keyUp',keyCode:'Space'});}
      else {window.webContents.sendInputEvent({type:'mouseMove',...point});window.webContents.sendInputEvent({type:'mouseDown',button:'left',clickCount:1,...point});window.webContents.sendInputEvent({type:'mouseUp',button:'left',clickCount:1,...point});}
      await until(()=>js(`document.querySelector(${JSON.stringify(selector)}).matches(':open')`),'native rounded dropdown opens '+selector);
      window.webContents.invalidate();await js('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))');
      const geometry=await js(`const select=document.querySelector(${JSON.stringify(selector)});const picker=getComputedStyle(select,'::picker(select)');({radius:parseFloat(picker.borderRadius),height:parseFloat(picker.height),appearance:getComputedStyle(select).appearance,rows:Array.from(select.options).filter(option=>!option.hidden).map(option=>{const r=option.getBoundingClientRect();return {height:r.height,left:r.left,right:r.right}}),viewport:innerWidth})`);
      assert(geometry.appearance==='base-select' && geometry.radius>=12 && geometry.height<=361 && geometry.rows.every(row=>row.height>=35 && row.left>=-1 && row.right<=geometry.viewport+1),'rounded dropdown rows fit viewport: '+selector+' '+JSON.stringify(geometry));
      if(name) await writeFile(resolve(project,'.agent/verification',name),(await window.webContents.capturePage(undefined,{stayHidden:true,stayAwake:true})).toPNG());
      if(choose!==undefined) {
        const optionPoint=await js(`const option=Array.from(document.querySelector(${JSON.stringify(selector)}).options).find(option=>option.value===${JSON.stringify(choose)});option.scrollIntoView({block:'nearest'});const r=option.getBoundingClientRect();({x:Math.round(r.left+r.width/2),y:Math.round(r.top+r.height/2)})`);
        optionPoint.x=Math.round(optionPoint.x*zoom);optionPoint.y=Math.round(optionPoint.y*zoom);
        window.webContents.sendInputEvent({type:'mouseMove',...optionPoint});window.webContents.sendInputEvent({type:'mouseDown',button:'left',clickCount:1,...optionPoint});window.webContents.sendInputEvent({type:'mouseUp',button:'left',clickCount:1,...optionPoint});
        await until(()=>js(`!document.querySelector(${JSON.stringify(selector)}).matches(':open')`),'native choice closes dropdown '+selector);
      }
    } finally {
      if(await js(`document.querySelector(${JSON.stringify(selector)}).matches(':open')`)) {window.webContents.sendInputEvent({type:'keyDown',keyCode:'Escape'});window.webContents.sendInputEvent({type:'keyUp',keyCode:'Escape'});await until(()=>js(`!document.querySelector(${JSON.stringify(selector)}).matches(':open')`),'Escape closes native dropdown '+selector);}
      if(ownDebugger) {await window.webContents.debugger.sendCommand('Emulation.setFocusEmulationEnabled',{enabled:false});window.webContents.debugger.detach();}
    }
