export async function runLiveSmoke({ window, actions, project }) {
  const js = code => window.webContents.executeJavaScript(code);
  async function until(test, name, timeout = 90000) {
    const deadline = Date.now() + timeout;
    while (Date.now() < deadline) { if (await test()) return; await delay(50); }
    throw new Error(`Live desktop check timed out: ${name}`);
  }
  const first = await actions.state(); assert.equal(first.keyStatus.deepseek, true, 'Windows DeepSeek environment key required');
  const testPath = resolve(first.project, 'greeting.test.mjs'); const hash = text => createHash('sha256').update(text).digest('hex');
  const originalTest = hash(await readFile(testPath));
  await until(() => js("!document.getElementById('send').disabled"), 'initial render');
  await js("document.getElementById('prompt').value = '请读取 hello.txt、package.json 和 greeting.test.mjs。先运行 npm test，确认测试失败；然后仅通过 edit 修改 hello.txt，将 Hello, world! 改为 Hello, coding agent!，保留 CRLF。不要修改测试或 package.json，不要读取其他路径，不要安装依赖。再运行 npm test 确认通过。最后用中文简要说明。'; document.getElementById('send').click()");
  await until(async () => (await actions.state()).lastResult != null, 'DeepSeek coding loop');
  const completed = await actions.state(); assert.equal(completed.lastResult.status, 'completed', JSON.stringify(completed.lastResult));
  assert.equal(await readFile(resolve(first.project, 'hello.txt'), 'utf8'), 'Hello, coding agent!\r\n');
  assert.equal(hash(await readFile(testPath)), originalTest);
  const history = await actions.history(); const results = history.entries.flatMap(entry => entry.data.kind === 'message' && entry.data.message.role === 'tool' ? [entry.data.message] : []);
  assert(results.some(result => result.name === 'shell' && result.isError), 'model observes failing test');
  assert(results.some(result => result.name === 'shell' && !result.isError && /(?:ℹ|#)\s*pass\s+1/.test(result.text)), 'model observes passing test');
  assert.equal((await actions.changes()).length, 1);
  await until(() => js("document.querySelectorAll('.change-card').length === 1 && document.querySelectorAll('.test-summary').length >= 2 && document.getElementById('stop').hidden"), 'rendered test results');
  await js('new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))'); await delay(100);
  const folder = resolve(project, '.agent/verification'); await mkdir(folder, { recursive: true });
  const screenshot = resolve(folder, 'desktop-deepseek.png'); await writeFile(screenshot, (await window.webContents.capturePage(undefined, { stayHidden: true, stayAwake: true })).toPNG());
  await js("document.getElementById('tools-tab').click()");
  await js('new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))'); await delay(100);
  await writeFile(resolve(folder, 'desktop-deepseek-tools.png'), (await window.webContents.capturePage(undefined, { stayHidden: true, stayAwake: true })).toPNG());
  const report = { timestamp: new Date().toISOString(), electron: process.versions.electron, model: completed.selectedModel, workspace: first.project,
    sessionPath: completed.agent.sessionPath, result: completed.lastResult, usage: completed.agent.usage, testFileUnchanged: true, changes: (await actions.changes()).length,
    tools: results.map(({ name, isError, details }) => ({ name, isError, details })), screenshot };
  await writeFile(resolve(folder, 'desktop-deepseek.json'), JSON.stringify(report, null, 2)); console.log(JSON.stringify(report, null, 2));
}
